 public JsonNode draftPolicy(ApplicationSessionIdentity.Verified subject,String context,String project,String key,byte[] bytes)throws Exception{
  keys(context,key,project);var request=codec.request("Policy",bytes);String hash=json.hash(request);var configuration=provider.configuration(text(request,"registration_id"));
  return tx(subject,a->{human(a,context);grantProject(a,project,"signing.policy.write");var prior=replay(a,project,"POLICY_DRAFT",key,hash);if(prior!=null)return prior;
   same(configuration,provider.configuration(text(request,"registration_id")));String policy=id();var now=permissions.databaseTime();var row=meta(a,project,now);put(row,"policy_revision",policy,"purpose",text(request,"purpose"),"policy_json",json.canonical(request),"policy_sha256",hash,"provider_json",json.canonical(configuration),"provider_sha256",json.hash(configuration));
   insert("version_registry",Map.of("tenant_id",a.context().tenant_id(),"owner_project_id",project,"version_id",policy,"entity_kind","SIGNING_POLICY","content_sha256",hash));insert("document_signing_policy",row);
   return finish(a,project,"POLICY_DRAFT",key,hash,request,json.tree(Map.of("policy_revision",policy,"status","DRAFT")),policy,"0",now);
  });
 }
