   var heads=db.queryForList("SELECT policy_revision FROM document_signing_policy_head WHERE tenant_id=? AND project_id=? AND purpose=? FOR UPDATE",a.context().tenant_id(),project,purpose);if(!Objects.equals(heads.isEmpty()?null:str(one(heads),"policy_revision"),expected))fail(ErrorCode.REVISION_CONFLICT);
