  var review=one(db.queryForList("SELECT baseline_json,baseline_sha256,request_json FROM document_review_confirmation_receipt WHERE tenant_id=? AND project_id=? AND operation_id=? FOR UPDATE",h.tenantId(),h.projectId(),text(proof.witness(),"operation_id")));var reviewBaseline=json.read(str(review,"baseline_json"));same(json.hash(reviewBaseline),str(review,"baseline_sha256"));
  ObjectNode out=JsonNodeFactory.instance.objectNode().put("document_id",h.documentId()).put("document_revision",h.documentRevision()).put("body_sha256",h.bodySha256()).put("plan_revision",h.planRevision()).put("template_version",h.templateVersion()).put("profile_revision",h.profileRevision()).put("snapshot_id",h.snapshotId()).put("auth_epoch",a.context().auth_epoch()).put("governance_epoch",a.context().governance_epoch()).put("evidence_watermark",fixed.watermarks().evidenceWatermark().toString()).put("issue_watermark",fixed.watermarks().issueWatermark().toString()).put("dependency_manifest_sha256",json.hash(fixed.dependencies())).put("policy_revision",str(policy,"policy_revision")).put("policy_sha256",str(policy,"policy_sha256")).put("provider_sha256",str(policy,"provider_sha256"));
  out.set("review_proof",proof.witness());out.set("review_baseline",reviewBaseline);out.set("review_ids",json.tree(decisions.stream().map(d->str(d,"review_id")).sorted().toList()));out.set("check_ids",json.read(str(review,"request_json")).required("check_ids"));out.set("dependencies",json.tree(fixed.dependencies()));out.set("body_object",json.tree(fixed.bodyObject()));out.set("plan",json.tree(plan));out.set("plan_current_dependencies",plans.confirmationDependencies(planGate));out.set("annotations",json.tree(annotations));out.set("authority",AgentPublicationWitness.tree(signer));out.set("document_baseline",reviewAuthority.requireForRead(a,context,fixed).baseline());
  // SG-01's fresh OIDC receipt is intentionally checked separately in sign(), never asserted here.
  out.set("verified_gates",json.tree(List.of("SG-01_AUTHORITY_POLICY","SG-02","SG-03","SG-04","SG-05","SG-06","SG-07","SG-08","SG-09")));return out;
