 private JsonNode verifySignature(EnterpriseAccess.Admission a,DocumentReadProtocol.Header h,byte[] bodyBytes,String signature)throws Exception{
  var record=one(db.queryForList("SELECT * FROM signature_record WHERE tenant_id=? AND project_id=? AND document_id=? AND document_revision=? AND signature_id=? FOR UPDATE",h.tenantId(),h.projectId(),h.documentId(),h.documentRevision(),signature));var body=one(db.queryForList("SELECT * FROM document_signed_content WHERE tenant_id=? AND project_id=? AND signature_id=? FOR UPDATE",h.tenantId(),h.projectId(),signature));var manifest=json.read(str(record,"manifest"));same(json.hash(manifest),str(record,"manifest_sha256"));same(str(record,"manifest_sha256"),str(record,"content_sha256"));same(manifest,json.read(str(body,"manifest_json")));same(json.canonical(manifest),str(body,"manifest_json"));same(SigningOidcProvider.hash(str(body,"manifest_json")),str(body,"manifest_sha256"));same(str(record,"manifest_sha256"),str(body,"manifest_sha256"));same(h.bodySha256(),str(body,"body_sha256"));same(WireValues.sha256((byte[])body.get("body_bytes")),h.bodySha256());if(!Arrays.equals(bodyBytes,(byte[])body.get("body_bytes")))bad();same(h.documentRevision(),text(manifest,"document_revision"));same(str(record,"signer_id"),text(manifest,"signer_id"));same(str(record,"policy_revision"),text(manifest,"policy_revision"));same(str(record,"purpose"),text(manifest,"purpose"));same(str(record,"reauthentication_ref"),text(manifest,"reauthentication_ref"));same(codec.manifest,str(record,"schema_manifest_sha256"));same(codec.manifest,str(body,"schema_manifest_sha256"));same("1.0.0",str(record,"schema_version"));same(str(record,"signer_id"),str(record,"created_by"));same(str(record,"created_by"),str(body,"created_by"));same(h.classification(),str(record,"classification"));same(h.classification(),str(body,"classification"));
  var receipt=one(db.queryForList("SELECT * FROM reauthentication_receipt WHERE tenant_id=? AND project_id=? AND reauthentication_ref=? FOR UPDATE",h.tenantId(),h.projectId(),str(record,"reauthentication_ref")));same("CONSUMED",str(receipt,"status"));same(str(record,"signer_id"),str(receipt,"subject_id"));same(record.get("signed_at"),receipt.get("consumed_at"));same(h.documentId(),str(receipt,"document_id"));same(h.documentRevision(),str(receipt,"document_revision"));same(str(record,"policy_revision"),str(receipt,"policy_revision"));same(str(record,"purpose"),str(receipt,"purpose"));
  var callback=one(db.queryForList("SELECT * FROM document_signing_callback WHERE tenant_id=? AND project_id=? AND callback_receipt_id=? AND challenge_id=? FOR UPDATE",h.tenantId(),h.projectId(),str(receipt,"callback_receipt_id"),str(receipt,"challenge_id")));same(json.hash(json.read(str(callback,"provider_evidence"))),str(callback,"evidence_sha256"));same(str(callback,"evidence_sha256"),text(manifest,"callback_evidence_sha256"));same(json.read(str(callback,"provider_evidence")),json.read(str(receipt,"provider_receipt_ref")));
  var registry=one(db.queryForList("SELECT entity_kind,content_sha256,owner_project_id FROM version_registry WHERE tenant_id=? AND version_id=? FOR UPDATE",h.tenantId(),signature));same("SIGNATURE",str(registry,"entity_kind"));same(h.projectId(),str(registry,"owner_project_id"));same(str(record,"manifest_sha256"),str(registry,"content_sha256"));
  var policy=policyRow(a,h.projectId(),str(record,"policy_revision"));same(json.hash(json.read(str(policy,"policy_json"))),str(policy,"policy_sha256"));same(str(policy,"policy_sha256"),text(manifest,"policy_sha256"));same(str(policy,"provider_sha256"),text(manifest,"provider_sha256"));
  var operation=one(db.queryForList("SELECT * FROM document_signing_operation WHERE tenant_id=? AND project_id=? AND signature_id=? AND operation_kind='SIGN' FOR UPDATE",h.tenantId(),h.projectId(),signature));var response=operationResponse(operation);same(signatureView(record,manifest),response.required("data"));same(str(record,"signer_id"),str(operation,"actor_id"));
  var input=json.read(str(operation,"request_json"));codec.validate("SignatureInput",input);same(json.hash(Map.of("document_id",h.documentId(),"request",input)),str(operation,"request_sha256"));
  var event=json.tree(Map.of("operation_id",str(operation,"operation_id"),"kind","SIGN","target_id",h.documentId(),"request_sha256",str(operation,"request_sha256"),"response_sha256",str(operation,"response_sha256")));
  var audit=one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND subject_id=? AND action='document.signing.sign' AND request_id=? AND result='SUCCESS' AND schema_manifest_sha256=? FOR UPDATE",h.tenantId(),h.projectId(),record.get("signer_id"),text(response,"request_id"),codec.manifest));same(event,json.read(str(audit,"resource_ref")));
  var outbox=one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND aggregate_revision=? AND event_type='document.signing.sign' FOR UPDATE",h.tenantId(),h.documentId(),text(response,"resource_revision")));same(event,json.read(str(outbox,"payload")));return signatureView(record,manifest);
 }
