 private JsonNode finish(EnterpriseAccess.Admission a,String project,String kind,String key,String hash,JsonNode request,JsonNode data,String target,String revision,LocalDateTime now,String classification)throws Exception{
  String operation=id(),requestId=id();codec.validate(switch(kind){case "SIGN"->"SignatureDetail";case "CHALLENGE"->"ReauthChallenge";case "COMPLETE"->"ReauthReceipt";case "POLICY_DRAFT"->"PolicyDraftReceipt";case "POLICY_APPROVE"->"PolicyApprovalReceipt";default->throw new IllegalStateException();},data);var response=envelope(data,revision,requestId);var op=new LinkedHashMap<String,Object>();put(op,"tenant_id",a.context().tenant_id(),"operation_id",operation,"subject_id",a.actorId(),"operation_name","SIGNING-"+kind,"idempotency_key",key,"request_sha256",hash,"state","COMPLETED","http_status",200,"response_ref",json.canonical(response),"target_id",target,"schema_version","1.0.0","schema_manifest_sha256",codec.manifest,"created_by",a.actorId(),"created_at",now,"classification",classification,"revision",1,"updated_at",now);insert("operation_record",op);
  var row=meta(a,project,now);row.put("classification",classification);put(row,"operation_id",operation,"actor_id",a.actorId(),"operation_kind",kind,"idempotency_key",key,"request_sha256",hash,"request_json",json.canonical(request),"target_id",target,"response_json",json.canonical(response),"response_sha256",json.hash(response),"signature_id","SIGN".equals(kind)?text(data,"signature_id"):null);insert("document_signing_operation",row);
  var event=json.tree(Map.of("operation_id",operation,"kind",kind,"target_id",target,"request_sha256",hash,"response_sha256",json.hash(response)));write(permissions.saveAudit(a.actorId(),project,id(),"document.signing."+kind.toLowerCase(Locale.ROOT),json.canonical(event),requestId,codec.manifest,classification));write(permissions.saveEvent(a.actorId(),id(),target,revision,"document.signing."+kind.toLowerCase(Locale.ROOT),json.canonical(event)));return response;
 }
