 private JsonNode envelope(JsonNode data,String revision,String request){var value=json.tree(new InterfaceProtocol.Envelope("1.0.0",request,revision,data));codec.validate("Envelope",value);return value;}
 private static Set<String> stringSet(JsonNode items){var s=new TreeSet<String>();items.forEach(i->s.add(i.asText()));return s;}
 private static LocalDateTime time(Map<String,Object> row,String k){Object v=row.get(k);if(v instanceof LocalDateTime t)return t;if(v instanceof java.sql.Timestamp t)return t.toLocalDateTime();throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
 private static void human(EnterpriseAccess.Admission a,String context){StrictComparisonAuthority.human(a,context);context(a,context);}
 private static void keys(String context,String key,String id){PermissionSchema.revision(context);SimulationInputArtifactSchema.key(key);WireValues.uuid(id);}
